mapper.select:
select count(*)
from users
where id = #{userId}

select count(*)
from content_items
where id = #{contentId}

select count(*)
from content_stats
where content_id = #{contentId}

mapper.update:
update content_stats
set like_count = #{stats.likeCount},
    comment_count = #{stats.commentCount},
    favorite_count = #{stats.favoriteCount},
    share_count = #{stats.shareCount}
where content_id = #{stats.contentId}

mapper.delete:
delete from media_assets
where content_id = #{contentId}
  and coalesce(delivery_type, 'progressive') <> 'hls'
